import asyncio, json
from playwright.async_api import async_playwright

URL="file:///workspace/chasen-writing/drafts/ai-design-skills-runs/repo-seed/runs/2026-10-29-r2/01-frontend-design/index.html"

JS = """
() => {
  const out = {};
  out.docW = document.documentElement.scrollWidth;
  out.winW = innerWidth;
  const over = [];
  document.querySelectorAll('*').forEach(el=>{
    const r = el.getBoundingClientRect();
    if (r.width>0 && (r.right > innerWidth+1 || r.left < -1)) {
      over.push({tag:el.tagName, cls:el.className && el.className.toString().slice(0,40), left:Math.round(r.left), right:Math.round(r.right), w:Math.round(r.width)});
    }
  });
  out.overflow = over.slice(0,15);
  const box = s => { const e=document.querySelector(s); if(!e) return null; const r=e.getBoundingClientRect(); return {x:Math.round(r.x),y:Math.round(r.y+scrollY),w:Math.round(r.width),h:Math.round(r.height)}; };
  out.h1 = box('h1');
  out.nameMask = box('.name-mask');
  out.heroGrid = box('.hero__grid');
  out.portrait = box('.portrait');
  out.heroBody = box('.hero__body');
  out.tagline = box('.hero__tagline');
  out.cta = box('.cta-row');
  out.facts = box('.hero__facts');
  out.heroTop = box('.hero__top');
  out.featured = box('.featured');
  out.mock = box('.appmock');
  out.aboutGrid = box('.about__grid');
  out.chibi = box('.about__aside');
  out.slot = box('.slot');
  out.fonts = {
    bricolage: document.fonts.check('16px "Bricolage Grotesque"'),
    noto: document.fonts.check('16px "Noto Sans SC"'),
  };
  const h1 = document.querySelector('h1');
  out.h1style = getComputedStyle(h1).fontFamily;
  out.bodyFont = getComputedStyle(document.body).fontFamily;
  out.sections = [...document.querySelectorAll('main section')].map(s=>{const r=s.getBoundingClientRect();return {id:s.id, top:Math.round(r.top+scrollY), h:Math.round(r.height)}});
  return out;
}
"""

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path="/usr/bin/google-chrome")
        for name,w,h in [("desk",1440,1000),("lap",1024,900),("tab",820,1000),("mob",390,844),("small",320,700)]:
            pg = await b.new_page(viewport={"width":w,"height":h})
            errs=[]
            pg.on("console", lambda m: errs.append(m.type+": "+m.text) if m.type in ("error","warning") else None)
            await pg.goto(URL)
            await pg.wait_for_timeout(1800)
            d = await pg.evaluate(JS)
            d["console"] = errs[:5]
            print(name, json.dumps(d, ensure_ascii=False))
            await pg.close()
        await b.close()
asyncio.run(main())
EOF
