JS="""()=>{
  function lines(el){
    const r=document.createRange(); const rects=[];
    const walk=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
    let n; while(n=walk.nextNode()){
      for(let i=0;i<n.length;i++){ r.setStart(n,i); r.setEnd(n,i+1);
        const b=r.getBoundingClientRect(); if(b.width===0&&b.height===0) continue;
        const y=Math.round(b.top);
        if(!rects.length||rects[rects.length-1].y!==y) rects.push({y,w:0,start:i}); 
        const last=rects[rects.length-1]; last.w=Math.max(last.w, Math.round(b.right));
      }
    }
    // approximate last line width by grouping y
    const groups={};
    const rw=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
    while(n=rw.nextNode()){
      for(let i=0;i<n.length;i++){ r.setStart(n,i); r.setEnd(n,i+1); const b=r.getBoundingClientRect();
        if(b.width===0) continue; const y=Math.round(b.top); (groups[y]=groups[y]||[]).push([b.left,b.right]);
      }
    }
    const ys=Object.keys(groups).map(Number).sort((a,b)=>a-b);
    return {lines:ys.length, lastWidth: ys.length? Math.round(Math.max(...groups[ys[ys.length-1]].map(p=>p[1])) - Math.min(...groups[ys[ys.length-1]].map(p=>p[0]))) : 0};
  }
  const out={};
  document.querySelectorAll('p, li, h2, h3, .slot__value').forEach((el,i)=>{
    const t=el.textContent.trim(); if(!t) return;
